SELECT MAX("MLB_21"."AVG") AS "TEMP_attr_AVG_qk__3030839854__0_",   MIN("MLB_21"."AVG") AS "TEMP_attr_AVG_qk__3417196579__0_",   MAX("MLB_21"."BABIP") AS "TEMP_attr_BABIP_qk__4285141330__0_",   MIN("MLB_21"."BABIP") AS "TEMP_attr_BABIP_qk__611967120__0_",   MAX("MLB_21"."ISO") AS "TEMP_attr_ISO_qk__2407168166__0_",   MIN("MLB_21"."ISO") AS "TEMP_attr_ISO_qk__3982906464__0_",   MAX("MLB_21"."wOBA") AS "TEMP_attr_wOBA_qk__1583528808__0_",   MIN("MLB_21"."wOBA") AS "TEMP_attr_wOBA_qk__2877628247__0_",   "MLB_21"."league" AS "league",   CAST("MLB_21"."times_faced" AS BIGINT) AS "times_faced",   CAST("MLB_21"."year" AS BIGINT) AS "year" FROM "MLB_21" WHERE ((CAST("MLB_21"."times_faced" AS BIGINT) = 1) AND (((CAST("MLB_21"."year" AS BIGINT) = 2012) AND ("MLB_21"."league" IN ('APPY', 'NYPL'))) OR ((CAST("MLB_21"."year" AS BIGINT) = 2013) AND ("MLB_21"."league" = 'NYPL')) OR ((CAST("MLB_21"."year" AS BIGINT) = 2014) AND ("MLB_21"."league" IN ('EL', 'FSL', 'SAL'))) OR ((CAST("MLB_21"."year" AS BIGINT) = 2015) AND ("MLB_21"."league" = 'EL')))) GROUP BY "league", "MLB_21"."times_faced", "MLB_21"."year", "times_faced", "year";
